MOD = 61
S3 = [0] * MOD

# Iterate over all possible values of x in {0, 1, ..., 60}
for x in range(MOD):
    # Calculate r = x^3 mod 61
    r = (x * x * x) % MOD
    # Increment the count for this residue r
    S3[r] += 1

# Output the counts for all residues r in {0, 1, ..., 60}
print("S3 counts for r = 0 to 60:")
for r in range(MOD):
    print(f"r={r}: {S3[r]}")
